import {Game} from './campaign.js';
import {drawPhoebe} from './phoebe-art.js';
import {drawHero} from './hero-art.js';
import {drawPixelFloor,drawPixelEnemy} from './pixel-art.js';
import {drawItemEffect} from './item-vfx.js';
import {prepareChapterArt} from './sprite-art.js';
const $=s=>document.querySelector(s),canvas=$('#demo'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
let game,kit='phoebe',target='still',automatic=true,paused=false,last=0,nextDash=1.8,dashRequest=false,aim={x:1,y:0},destination=null;const keys=new Set();
const kits={phoebe:{ids:['phoebe'],title:'菲比单独',text:'菲比先蓄力 0.35 秒，再展开电线 0.4 秒。初始每次命中 1.5 点伤害，随当前面板攻击成长，单次最高 3.2，同一敌人每 0.4 秒最多一次；布线冷却 3.8 秒，最多 3 条。'},wire:{ids:['phoebewire'],title:'蛙跳电线',text:'蛙跳落地后沿路径通电。初始攻击时每次命中 2，间隔 0.4 秒；伤害实时随面板攻击成长，无固定伤害上限，最多 2 条。房间内不消失，新线替换最早的线。'},combo:{ids:['phoebe','phoebewire'],title:'菲比＋蛙跳电线',text:'共用 3 条电线上限。初始攻击时蛙跳线每次命中 2.4，菲比线初始为 1.5、随攻击成长至最高 3.2；交叉处只取最高伤害，不叠伤。'}};
function reset(){game=new Game(()=>.42);game.start();game.items=[...kits[kit].ids];game.room.type='fight';game.room.clear=false;game.room.obstacles=[];game.room.hazards=[];game.room.loot=[];game.p.x=300;game.p.y=300;game.p.inv=1e9;game.hurt=()=>{};game.enemyAttack=()=>true;game.enemySpeed=()=>target==='chase'?95:0;const e=game.spawn(target==='fly'?'hopper':'brute',kit==='phoebe'?550:420,kit==='phoebe'?348:300);e.hp=e.maxHp=1000;e.cd=1e9;game.room.enemies=[e];nextDash=1.8;dashRequest=false;destination=null;aim={x:1,y:0};keys.clear();paused=false;$('#pause').textContent='暂停';$('#kitTitle').textContent=kits[kit].title;$('#explain').textContent=kits[kit].text;prepareChapterArt(1);}
for(const b of document.querySelectorAll('[data-kit]'))b.onclick=()=>{kit=b.dataset.kit;for(const c of document.querySelectorAll('[data-kit]'))c.setAttribute('aria-pressed',String(c===b));reset()};
$('#target').onchange=e=>{target=e.target.value;reset()};$('#auto').onclick=()=>{automatic=!automatic;destination=null;$('#auto').textContent='自动演示：'+(automatic?'开':'关');$('#auto').setAttribute('aria-pressed',automatic);nextDash=game.elapsed+.5;canvas.focus()};$('#reset').onclick=reset;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'继续':'暂停';keys.clear();destination=null;dashRequest=false};$('#dash').onclick=()=>{dashRequest=true};
canvas.addEventListener('pointerdown',e=>{if(automatic)return;canvas.focus();const r=canvas.getBoundingClientRect();destination={x:Math.max(90,Math.min(870,(e.clientX-r.left)*960/r.width)),y:Math.max(90,Math.min(510,(e.clientY-r.top)*600/r.height))};const dx=destination.x-game.p.x,dy=destination.y-game.p.y;aim=Math.abs(dx)>Math.abs(dy)?{x:Math.sign(dx),y:0}:{x:0,y:Math.sign(dy)}});
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(document.activeElement?.tagName))return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k===' '&&!e.repeat)dashRequest=true;if(k.startsWith('arrow'))aim=({arrowup:{x:0,y:-1},arrowdown:{x:0,y:1},arrowleft:{x:-1,y:0},arrowright:{x:1,y:0}})[k]});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function suspend(){paused=true;keys.clear();destination=null;dashRequest=false;$('#pause').textContent='继续'}window.addEventListener('blur',suspend);document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend()});
function update(dt){if(paused)return;let mx=0,my=0,dash=false;
 if(automatic&&kit!=='phoebe'&&game.elapsed>=nextDash&&game.p.dashCD<=0){aim={x:game.p.x<430?1:-1,y:0};dash=true;nextDash=game.elapsed+3;}
 if(!automatic){mx=Number(keys.has('d'))-Number(keys.has('a'));my=Number(keys.has('s'))-Number(keys.has('w'));if(destination&&!mx&&!my){const dx=destination.x-game.p.x,dy=destination.y-game.p.y,d=Math.hypot(dx,dy);if(d>6){mx=dx/d;my=dy/d}else destination=null}}
 if(dashRequest){if(game.p.dashCD<=0)dash=true;dashRequest=false}if(dash){mx=aim.x;my=aim.y;destination=null}game.update(dt,{mx,my,dash});game.heroMoving=Math.hypot(mx,my)>0;
 for(const event of game.events.splice(0))if(event.type==='dash')game.heroLandUntil=0;
}
function draw(){ctx.clearRect(0,0,960,600);drawPixelFloor(ctx,game.room,1);drawPhoebe(ctx,game);for(const e of game.room.enemies){drawPixelEnemy(ctx,e,game.elapsed);ctx.fillStyle='#273e34';ctx.font='bold 18px system-ui';ctx.textAlign='center';ctx.fillText(target==='fly'?'飞行靶':target==='chase'?'追击靶':'地面靶',e.x,e.y-66);ctx.fillText(e.hp.toFixed(1)+' / 1000',e.x,e.y-43)}drawHero(ctx,game,game.p.x,game.p.y,1,false,{costumeId:'original'});for(const f of game.effects)drawItemEffect(ctx,f);const dealt=game.room.enemies.reduce((s,e)=>s+1000-e.hp,0);$('#damage').textContent=dealt.toFixed(2);$('#elapsed').textContent=game.elapsed.toFixed(1)+' 秒';$('#dps').textContent=(dealt/Math.max(1,game.elapsed)).toFixed(2);$('#lines').textContent=(game.phoebeWires?.length||0)+' / '+(kit==='wire'?2:3);const phase=game.phoebe?.phase;$('#phase').textContent=paused?'已暂停':phase==='windup'?'菲比：蓄力甩插头':phase==='unroll'?'菲比：电线展开中，尚未通电':phase==='recover'?'菲比：布线完成，进入冷却':game.p.dash>0?'奶蛙：蛙跳布线中，落地后通电':kit==='wire'?'等敌人踩线：每 0.4 秒结算一次':'菲比：跟随 / 寻找可布线目标';$('#dash').disabled=paused||game.p.dashCD>0;$('#dash').textContent=game.p.dashCD>0?'蛙跳 '+game.p.dashCD.toFixed(1)+'s':(aim.y<0?'向上':aim.y>0?'向下':aim.x<0?'向左':'向右')+'蛙跳';}
function frame(now){const dt=Math.max(0,Math.min(.04,(now-last)/1000||0));last=now;update(dt);draw();requestAnimationFrame(frame)}reset();requestAnimationFrame(frame);
